/** Original Moke schematic; generated bytes contain no client drawing or third-party artwork. */
export function createHeroPdf(
  revision: "A" | "B",
  rotation: 0 | 90 | 180 | 270 = 0,
  userUnit = 1,
  inset = 0,
): Uint8Array {
  const text = (x: number, y: number, size: number, value: string) =>
    `BT /F1 ${size} Tf ${x} ${y} Td (${value}) Tj ET`;

  const light = (x: number, y: number, label: string) =>
    [
      `${x - 12} ${y - 12} 24 24 re S`,
      `${x - 12} ${y - 12} m ${x + 12} ${y + 12} l S`,
      `${x - 12} ${y + 12} m ${x + 12} ${y - 12} l S`,
      text(x - 4, y - 30, 11, label),
    ].join("\n");

  const plan = [
    "0.6 w",
    text(40, 750, 22, "MOKE COORDINATION LAB"),
    text(40, 725, 12, `L-101 | FLOOR 1 LIGHTING PLAN | REV ${revision}`),
    text(40, 703, 10, "Original schematic fixture. Coordinate fixture quantities with L-601."),
    "60 360 230 300 re S",
    "320 360 230 300 re S",
    text(80, 635, 14, "ROOM 101 / TYPE A"),
    text(340, 635, 14, "ROOM 102 / TYPE B"),
    light(120, 540, "A"),
    light(230, 540, "A"),
    ...(revision === "B" ? [light(175, 440, "A")] : []),
    light(380, 540, "B"),
    light(490, 540, "B"),
    text(60, 330, 12, "SCOPE: all fixtures within each room boundary."),
    text(60, 310, 12, "Symbols in the legend are examples, not installed devices."),
    text(40, 50, 10, "L-101 | Moke authored test source | dimensions in PDF points"),
  ];

  // Dense, deterministic drafting texture also exercises media transfer beyond 64 KiB.
  for (let i = 0; i < 160; i++) {
    const x = 40 + i * 3.3;
    plan.push(`0.8 G 0.15 w ${x} 100 m ${x + 19} ${180 + (i % 19)} l S`);
  }

  plan.push("0 G");

  const schedule = [
    "0.6 w",
    text(40, 750, 22, "MOKE COORDINATION LAB"),
    text(40, 725, 12, "L-601 | FIXTURE SCHEDULE AND CONTROL DETAIL"),
    text(
      40,
      700,
      10,
      "Scope and quantities are explicit project requirements, not code thresholds.",
    ),
    "60 500 490 140 re S",
    text(80, 615, 14, "ROOM        TYPE        REQUIRED QUANTITY"),
    text(80, 575, 14, "101                A                         3"),
    text(80, 540, 14, "102                B                         2"),
    text(60, 450, 14, "CONTROL DETAIL: TYPE C / TWO FIXTURES"),
    "60 280 490 130 re S",
    light(180, 350, "C"),
    light(420, 350, "C"),
    text(60, 250, 12, "CONTROL SCHEDULE: TYPE C REQUIRED QUANTITY = 2"),
    text(60, 225, 10, "This independent detail remains unchanged in Revision B."),
    text(40, 50, 10, "L-601 | Moke authored test source | unchanged detail"),
  ];

  const stream = (content: string) =>
    `<< /Length ${new TextEncoder().encode(content).length} >>\nstream\n${content}\nendstream`;

  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Count 2 /Kids [3 0 R 4 0 R] >>",
    `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /CropBox [${inset} ${inset} ${612 - inset} ${792 - inset}] /Rotate ${rotation} /UserUnit ${userUnit} /Resources << /Font << /F1 5 0 R >> >> /Contents 6 0 R >>`,
    `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /CropBox [${inset} ${inset} ${612 - inset} ${792 - inset}] /Rotate ${rotation} /UserUnit ${userUnit} /Resources << /Font << /F1 5 0 R >> >> /Contents 7 0 R >>`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    stream(plan.join("\n")),
    stream(schedule.join("\n")),
  ];

  let pdf = "%PDF-1.7\n";
  const offsets = [0];

  for (const [index, object] of objects.entries()) {
    offsets.push(new TextEncoder().encode(pdf).length);
    pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
  }

  const xref = new TextEncoder().encode(pdf).length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;

  for (const offset of offsets.slice(1)) pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;

  return new TextEncoder().encode(pdf);
}
